function draw() {
  if (k < iters) {
    let r = 200; //random(-200, 200) 
		let a = random(TWO_PI);
		let nx = r * cos(a) + h / 2;
		let ny = r * sin(a) + h / 2;
		
		g = new chunk(...pool[k], random(20, 400), random(pal), p);
			
